//p5.js shader basic structure ref from https://www.openprocessing.org/sketch/923286

let sha;
let canvas;
let pos;
let angle;
let vel = 0;
//let wyrd = 'DISRUPT';
var wyrd = "DISRUPT".split('');
let xPos = 0;

function preload(){
	sha = createShader(vert, frag);
	WebFont.load({google: {families:["Roboto:900"]}});
}

function setup() {
	createCanvas(1112, 834, WEBGL);
	canvas = createGraphics(width, height, WEBGL);
	//canvas.noStroke();

}

function draw() {
	background(255);

	if(frameCount<2){
		//it could be in the setup
		//but it does not work to draw text in the setup like this
		//dont know why
		var myText = createGraphics(width, height);
		myText.colorMode(HSB, 255);
		myText.noStroke();
		/*myText.stroke(0);
		myText.strokeWeight(3);*/
		myText.textFont("Roboto");
		myText.textSize(200);
		//myText.textAlign(CENTER, CENTER);
		for (let t = 0; t < wyrd.length; t++){
			xPos += myText.textWidth(wyrd[t-1]);
			myText.fill(t/wyrd.length*255, 255, 255);
		  myText.text(wyrd[t], -width*.7 + xPos, height/2+50);
		}
		canvas.image(myText, -width/2, -height/2);
	}

	canvas.shader(sha);
	sha.setUniform('resolution', [width, height]);
	sha.setUniform('time', millis()/1000);
	sha.setUniform('mouse', [(window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY)))]);
	sha.setUniform('tex', canvas);
	sha.setUniform('vel', vel);
	canvas.rect(-width/2, -height/2, width, height);
	image(canvas, -width/2, -height/2);

	vel *= 0.95;

	if(pos){
		fill(255, 0, 0);
		stroke(255, 0, 0);
		circle(pos.x, pos.y, 10);
		const radius = 1000;
		line(
			cos(angle) * radius + pos.x,
			sin(angle) * radius + pos.y,
			cos(angle) * -radius + pos.x,
			sin(angle) * -radius + pos.y
		);
	}
}

function mousePressed(){
	pos = createVector((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX)))-width/2, (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY)))-height/2);
	angle = 0;
}

function mouseDragged(){
	if(pos)
		angle = atan2((window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY)))-height/2 - pos.y, (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX)))-width/2 - pos.x);
}

function mouseReleased(){
	if(pos){
		canvas.shader(sha);
		sha.setUniform('angle', angle);
		sha.setUniform('pos', [(pos.x+width/2)/width, (pos.y+height/2)/height]);
		vel = 1;
		pos = undefined;
	}
}

// === Tab: frag ===
const frag = `
	precision highp float;

	// Processing specific input
	uniform float time;
	uniform vec2 resolution;
	uniform vec2 mouse;

	// Layer between Processing and Shadertoy uniforms
	vec3 iResolution = vec3(resolution,0.0);
	vec2 iMouse = vec2(mouse.xy);

	#define PI 3.1415926535
	#define TWO_PI 6.283185307
	#define iTime time
	//#define fragCoord gl_FragCoord.xy
	#define fragCoord var_vertTexCoord.xy * iResolution.xy
	#define fragColor gl_FragColor

	//attributes, in
	varying vec4 var_centerGlPosition;
	varying vec3 var_vertNormal;
	varying vec2 var_vertTexCoord;

	//custom
	uniform sampler2D tex;
	uniform vec2 pos;
	uniform float angle;
	uniform float vel;

	vec2 round(vec2 n){
		return floor(n+0.5);
	}

	//from @etale_cohomology
	//https://www.shadertoy.com/view/4dSBDh
	//return from 0 to TWO_PI
	float atan3(vec2 st){
			return mod(atan(st.t, st.s), TWO_PI);
	}

	void main(){
		vec2 uv = fragCoord / iResolution.xy;
		vec2 move = vec2(0., 0.);
		if(vel>0.01){
			//float polarAngle = atan3(uv - pos);
			float polarAngle = atan(uv.y - pos.y, uv.x - pos.x);
			float res = mod(polarAngle - angle, TWO_PI);
			//gl_FragColor = vec4(res/TWO_PI, 0.0, 0.0, 1.0);
			//return;
			float dir = res > PI ? 1. : -1.;
			move.x = cos(angle + PI/2.) * vel/1000. * dir;
			move.y = sin(angle + PI/2.) * vel/1000. * dir;
			//fix the blur, but creates a rotation bug
			//move = round(move * iResolution.xy) / iResolution.xy;
		}
		vec4 color = texture2D(tex, uv + move);
		gl_FragColor = color;
	}
`;

// === Tab: vert ===
//ref 3d shader from https://www.openprocessing.org/sketch/881537

const vert = `
	precision highp float;

    // attributes, in
    attribute vec3 aPosition;
    attribute vec3 aNormal;
    attribute vec2 aTexCoord;

    // attributes, out
    varying vec3 var_vertPos;
    varying vec3 var_vertNormal;
    varying vec2 var_vertTexCoord;
		varying vec4 var_centerGlPosition;//origin

    // matrices
    uniform mat4 uModelViewMatrix;
    uniform mat4 uProjectionMatrix;
    uniform mat3 uNormalMatrix;
		uniform float u_time;


    void main() {
      vec3 pos = aPosition;
			vec4 posOut = uProjectionMatrix * uModelViewMatrix * vec4(pos, 1.0);
      gl_Position = posOut;

      // set out value
      var_vertPos      = pos;
      var_vertNormal   = aNormal;
      var_vertTexCoord = aTexCoord;
			var_centerGlPosition = uProjectionMatrix * uModelViewMatrix * vec4(0., 0., 0., 1.);
    }
`;

